fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since both `a` and `b` have the same length and every element in `b` is non-zero,
    // we can safely zip them together and compute `x % y` for each pair.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x % y)
     .collect()
}

